1	package net.officefloor.hq.app;
2	
3	import java.time.LocalDate;
4	import java.util.List;
5	import java.util.Map;
6	import org.springframework.context.annotation.Profile;
7	import org.springframework.jdbc.core.JdbcTemplate;
8	import org.springframework.web.bind.annotation.PostMapping;
9	import org.springframework.web.bind.annotation.RequestBody;
10	import org.springframework.web.bind.annotation.RequestMapping;
11	import org.springframework.web.bind.annotation.RestController;
12	
13	/**
14	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
15	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
16	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
17	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
18	 */
19	@Profile("harness")
20	@RestController
21	@RequestMapping("/__test__")
22	public class TestSupportController {
23	
24	    private final Audit audit;
25	    private final JdbcTemplate jdbc;
26	
27	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
28	        this.audit = audit;
29	        this.jdbc = jdbc;
30	    }
31	
32	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
33	    @PostMapping("/reset")
34	    public void reset() {
35	        audit.clear();
36	        // Disable FK checks so a referenced parent (clients) can be truncated alongside its child.
37	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
38	        jdbc.execute("TRUNCATE TABLE invoices RESTART IDENTITY");
39	        jdbc.execute("TRUNCATE TABLE projects RESTART IDENTITY");
40	        jdbc.execute("TRUNCATE TABLE clients RESTART IDENTITY");
41	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
42	    }
43	
44	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
45	    @PostMapping("/seed")
46	    @SuppressWarnings("unchecked")
47	    public void seed(@RequestBody Map<String, Object> fixture) {
48	        List<Map<String, Object>> clients =
49	                (List<Map<String, Object>>) fixture.getOrDefault("clients", List.of());
50	        long maxClientId = 0;
51	        for (Map<String, Object> client : clients) {
52	            long id = ((Number) client.get("id")).longValue();
53	            // Seed with the fixture's explicit id (JdbcTemplate, not JPA) so specs can assert by id.
54	            jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
55	                    id, client.get("name"), client.get("email"));
56	            maxClientId = Math.max(maxClientId, id);
57	        }
58	        if (maxClientId > 0) {
59	            // Advance the identity so app-generated ids don't collide with seeded rows.
60	            jdbc.execute("ALTER TABLE clients ALTER COLUMN id RESTART WITH " + (maxClientId + 1));
61	        }
62	
63	        List<Map<String, Object>> projects =
64	                (List<Map<String, Object>>) fixture.getOrDefault("projects", List.of());
65	        long maxProjectId = 0;
66	        for (Map<String, Object> project : projects) {
67	            long id = ((Number) project.get("id")).longValue();
68	            long clientId = ((Number) project.get("clientId")).longValue();
69	            jdbc.update("INSERT INTO projects (id, name, client_id) VALUES (?, ?, ?)",
70	                    id, project.get("name"), clientId);
71	            maxProjectId = Math.max(maxProjectId, id);
72	        }
73	        if (maxProjectId > 0) {
74	            jdbc.execute("ALTER TABLE projects ALTER COLUMN id RESTART WITH " + (maxProjectId + 1));
75	        }
76	
77	        List<Map<String, Object>> invoices =
78	                (List<Map<String, Object>>) fixture.getOrDefault("invoices", List.of());
79	        long maxInvoiceId = 0;
80	        for (Map<String, Object> invoice : invoices) {
81	            long id = ((Number) invoice.get("id")).longValue();
82	            long projectId = ((Number) invoice.get("projectId")).longValue();
83	            double amount = ((Number) invoice.get("amount")).doubleValue();
84	            String status = (String) invoice.getOrDefault("status", "UNPAID");
85	            Object issuedDate = invoice.getOrDefault("issuedDate", LocalDate.now().toString());
86	            Object dueDate = invoice.getOrDefault("dueDate", LocalDate.now().toString());
87	            jdbc.update(
88	                    "INSERT INTO invoices (id, project_id, amount, status, issued_date, due_date) VALUES (?, ?, ?, ?, ?, ?)",
89	                    id, projectId, amount, status, issuedDate, dueDate);
90	            maxInvoiceId = Math.max(maxInvoiceId, id);
91	        }
92	        if (maxInvoiceId > 0) {
93	            jdbc.execute("ALTER TABLE invoices ALTER COLUMN id RESTART WITH " + (maxInvoiceId + 1));
94	        }
95	    }
96	}
